package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class TarUtils_parseOctal_TriageGen2Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // length is 7, offset 0. Trailing space is trimmed.
        assertEquals(83L, TarUtils.parseOctal(buffer, 0, 7));
    }

    @Test
    public void testParseOctal_ValidWithLeadingSpaces() {
        byte[] buffer = "   0755 ".getBytes();
        assertEquals(493L, TarUtils.parseOctal(buffer, 0, 8));
    }

    @Test
    public void testParseOctal_ValidWithNulAndSpaces() {
        byte[] buffer = " 0123\0\0 ".getBytes();
        // The logic trims trailing NULs/spaces.
        // " 0123\0\0 " -> end-1 is ' ', end-- -> end-1 is '\0' -> end-- -> end-1 is '\0' -> end--
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_LeadingZeroBuffer() {
        byte[] buffer = new byte[]{0, 0, 0, 0};
        assertEquals(0L, TarUtils.parseOctal(buffer, 0, 4));
    }

    @Test
    public void testParseOctal_LengthTooShort() {
        byte[] buffer = "1".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 1);
            fail("Should have thrown IllegalArgumentException for length < 2");
        } catch (IllegalArgumentException e) {
            assertEquals("Length 1 must be at least 2", e.getMessage());
        }
    }

    @Test
    public void testParseOctal_InvalidTrailingCharacter() {
        // The last character must be ' ' or 0 (NUL)
        byte[] buffer = "01234X".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 6);
            fail("Should have thrown IllegalArgumentException for invalid trailer");
        } catch (IllegalArgumentException e) {
            // message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_InvalidOctalDigit() {
        // '8' and '9' are not valid octal digits
        byte[] buffer = "0128 ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 5);
            fail("Should have thrown IllegalArgumentException for invalid octal digit");
        } catch (IllegalArgumentException e) {
            // message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_NonDigitCharacter() {
        byte[] buffer = "01A ".getBytes();
        try {
            TarUtils.parseOctal(buffer, 0, 4);
            fail("Should have thrown IllegalArgumentException for non-digit character");
        } catch (IllegalArgumentException e) {
            // message contains exceptionMessage details
        }
    }

    @Test
    public void testParseOctal_OffsetAndLength() {
        byte[] buffer = "junk 0777 \0";
        // offset 5, length 6 -> "0777 \0"
        // index 5='0', 6='7', 7='7', 8='7', 9=' ', 10='\0'
        // This tests that the method respects the offset and length parameters
        assertEquals(511L, TarUtils.parseOctal(buffer, 5, 6));
    }

    @Test
    public void testParseOctal_ComplexTrailing() {
        // Test the while loop for multiple trailing NULs and spaces
        byte[] buffer = "012\0 \0  ".getBytes();
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }

    @Test
    public void testParseOctal_SingleDigitWithSpace() {
        byte[] buffer = "7 ".getBytes();
        assertEquals(7L, TarUtils.parseOctal(buffer, 0, 2));
    }
}
